/**
 * TypeScript types for a Base project's database, generated by the project's own postgres-meta (`/generators/typescript`,
 * the same generator `supabase gen types typescript` uses), reached through the project gateway's `/pg` route with the
 * service key — the control plane never talks to the meta container directly. (compat area: `levant base gen types`)
 */
import { db } from "@/lib/db";
import { containerIp } from "./compose";
import { gatewayContainer, publicNetwork } from "./config";
import { decryptSecrets } from "./secrets";

const SCHEMA_RE = /^[a-z_][a-z0-9_]{0,62}$/;

export async function generateTypes(ref: string, opts: { schemas?: string[]; timeoutMs?: number } = {}): Promise<string> {
  const p = await db.baseProject.findUnique({ where: { ref } });
  if (!p) throw new Error("Base project not found");
  if (p.status !== "ACTIVE") throw new Error(`Project is ${p.status}`);
  const schemas = opts.schemas?.length ? opts.schemas : ["public"];
  const bad = schemas.find((s) => !SCHEMA_RE.test(s));
  if (bad) throw new Error(`Invalid schema name ${bad}`);
  const ip = await containerIp(gatewayContainer(ref), publicNetwork());
  if (!ip) throw new Error("Gateway is not running");
  const { serviceRoleKey } = decryptSecrets(p.secretsEnc);
  const q = new URLSearchParams({ included_schemas: schemas.join(","), detect_one_to_one_relationships: "true" });
  const res = await fetch(`http://${ip}:8000/pg/generators/typescript?${q}`, {
    headers: { apikey: serviceRoleKey, Authorization: `Bearer ${serviceRoleKey}` },
    signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`type generator failed (${res.status}): ${text.slice(0, 300)}`);
  return text;
}
